/* @autogenerated */
import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, ValidatorFn, Validators } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { ActionParam, ActionParamValues, ActionParamsOptions } from './action-params-dialog.service';

@Component({
  selector: 'action-params-dialog',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    MatDialogModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatCheckboxModule,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  styles: `
    .action-params {
      display: flex;
      flex-direction: column;
      gap: var(--app-space-2, 8px);
      min-width: min(420px, 80vw);
    }
  `,
  template: `
    <h2 mat-dialog-title>{{ data.title }}</h2>
    <mat-dialog-content>
      @if (data.message) {
        <p>{{ data.message }}</p>
      }
      <form class="action-params" [formGroup]="form" (ngSubmit)="accept()">
        @for (param of data.params; track param.name) {
          @switch (param.type) {
            @case ('boolean') {
              <mat-checkbox [formControlName]="param.name">{{ param.label }}</mat-checkbox>
            }
            @case ('select') {
              <mat-form-field>
                <mat-label>{{ param.label }}</mat-label>
                <mat-select [formControlName]="param.name" [required]="!!param.required">
                  @for (option of param.options ?? []; track option.value) {
                    <mat-option [value]="option.value">{{ option.label }}</mat-option>
                  }
                </mat-select>
                @if (param.hint) {
                  <mat-hint>{{ param.hint }}</mat-hint>
                }
              </mat-form-field>
            }
            @case ('textarea') {
              <mat-form-field>
                <mat-label>{{ param.label }}</mat-label>
                <textarea matInput rows="3" [formControlName]="param.name" [required]="!!param.required"></textarea>
                @if (param.hint) {
                  <mat-hint>{{ param.hint }}</mat-hint>
                }
              </mat-form-field>
            }
            @default {
              <mat-form-field>
                <mat-label>{{ param.label }}</mat-label>
                <input
                  matInput
                  [type]="inputType(param)"
                  [formControlName]="param.name"
                  [required]="!!param.required"
                />
                @if (param.hint) {
                  <mat-hint>{{ param.hint }}</mat-hint>
                }
              </mat-form-field>
            }
          }
        }
      </form>
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button matButton type="button" [mat-dialog-close]="null">{{ data.cancel }}</button>
      <button matButton="filled" type="button" [disabled]="form.invalid" (click)="accept()">{{ data.ok }}</button>
    </mat-dialog-actions>
  `,
})
export class ActionParamsDialogComponent {
  readonly data = inject<ActionParamsOptions>(MAT_DIALOG_DATA);
  private readonly ref: MatDialogRef<ActionParamsDialogComponent, ActionParamValues | null> = inject(MatDialogRef);
  readonly form = new FormGroup<Record<string, FormControl<unknown>>>(
    Object.fromEntries(this.data.params.map((param) => [param.name, this.control(param)])),
  );

  inputType(param: ActionParam): string {
    switch (param.type) {
      case 'number':
        return 'number';
      case 'date':
        return 'date';
      case 'datetime':
        return 'datetime-local';
      default:
        return 'text';
    }
  }

  accept(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const values: ActionParamValues = {};
    for (const param of this.data.params) {
      values[param.name] = this.valueOf(param, this.form.controls[param.name].value);
    }
    this.ref.close(values);
  }

  private control(param: ActionParam): FormControl<unknown> {
    const validators: ValidatorFn[] = [];
    if (param.required) {
      validators.push(param.type === 'boolean' ? Validators.requiredTrue : Validators.required);
      if (param.type === 'text' || param.type === 'textarea') {
        // Un texto en blanco cuenta como vacío, como en las precondiciones
        validators.push(Validators.pattern(/\S/));
      }
    }
    return new FormControl<unknown>(param.type === 'boolean' ? false : null, validators);
  }

  /** Los textos sin espacios a los lados, los números como número y las fechas como `Date`; lo vacío, `null`. */
  private valueOf(param: ActionParam, value: unknown): unknown {
    if (value === null || value === undefined || value === '') {
      return param.type === 'boolean' ? false : null;
    }
    switch (param.type) {
      case 'number':
        return Number(value);
      case 'date':
      case 'datetime':
        return new Date(value as string);
      case 'text':
      case 'textarea':
        return String(value).trim() || null;
      default:
        return value;
    }
  }
}
